apiVersion: aegismesh/v1
kind: Profile
metadata: {id: payments-guard, nameKo: 결제 에이전트 보호}
spec:
  extends: chatbot-baseline
  select:
    - {domain: [D3]}
    - {id: [D5-01, D6-03]}
  policyOverrides:
    D3-05: {verdict: block}
  evidence: {retentionDays: 365, payload: masked}
  region: {modelEgress: deny}
  defaultStage: partial

secrets:
  existingSecret: {0}       # 키: DB_PASSWORD · LEDGER_SIGNING_KEY · SVID_SIGNING_KEY · AUTH_SECRET
api:
  replicas: {1}
persistence:
  accessMode: {2}{3}
postgresql:
  enabled: {4}{5}
collector:
  enabled: {6}
ingress:
  enabled: {7}{8}
